"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5911],{826(e){e.exports=JSON.parse('{"title":"\uc5d0\uc774\uc804\ud2b8 \ud14c\uc2a4\ud2b8\ub294 \uc5b4\ub514\uc5d0 \uc5b9\ud788\ub294\uac00","date":"2026-06-17","coverUrl":"/kudzu-based-bench/assets/notion/9df13ae1a43bb8fa.png","html":"<h1 data-notion-block-id=\\"379e548d-8a8e-80d2-803b-e5c9e3e04f57\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"381e548d-8a8e-807e-a618-c26fd360a759\\" id=\\"381e548d-8a8e-807e-a618-c26fd360a759\\">\uc5d0\uc774\uc804\ud2b8 \ud14c\uc2a4\ud2b8\ub294 \uc5b4\ub514\uc5d0 \uc5b9\ud788\ub294\uac00</h2><a href=\\"https://slack.engineering/agentic-testing-where-agents-fit-in-the-e2e-testing-stack/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://slack.engineering/agentic-testing-where-agents-fit-in-the-e2e-testing-stack/</a><p data-notion-block-id=\\"381e548d-8a8e-805c-a0f3-d3ac79cede02\\">\uc5d0\uc774\uc804\ud2b8\ub85c \ud14c\uc2a4\ud2b8\ub97c \ub3cc\ub9b4 \ub54c \ube44\uc6a9\uacfc \uc2e0\ub8b0\uc131\uc744 \uac00\ub974\ub294 \uac74 \uc5b4\ub5a4 \ubaa8\ub378\uc744 \uc4f0\ub290\ub0d0\uac00 \uc544\ub2c8\ub77c \uc5d0\uc774\uc804\ud2b8\uac00 \ub3c4\uad6c\uc640 \ub9e5\ub77d\uc744 \uc8fc\uace0\ubc1b\ub294 \uad6c\uc870\ub77c\ub294 \uac78 \uc2e4\uce21\uc73c\ub85c \ub4dc\ub7ec\ub0b4\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc6a9\uc740 \ubaa8\ub378\uc758 \ucd9c\ub825\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \ub300\ud654\ub97c \ub9e4 \ud134 \ub2e4\uc2dc \ud758\ub824\ubcf4\ub0b4\ub294 \ub370\uc11c \uc313\uc774\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \uc65c \ud14c\uc2a4\ud2b8\ud558\ub294\uac00\ub77c\ub294 \ub354 \uc55e\uc120 \uc9c8\ubb38\uc740 \ud14c\uc2a4\ud305 \ud2b8\ub85c\ud53c\ub97c \ub2e4\ub8ec <a href=\\"https://ones-to-watch.ethansup.net/news/post/b6be5023-1604-4d2d-9f86-d1888a427413\\">\uc5b4\ub5bb\uac8c \ud14c\uc2a4\ud2b8\ud574\uc57c \ud558\ub294\uac00</a>\uc5d0\uc11c \uc9da\uc5c8\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"381e548d-8a8e-80a3-9c4d-c3cd600d05f2\\" id=\\"381e548d-8a8e-80a3-9c4d-c3cd600d05f2\\">Flow \uc720\uc800\uac00 TypeScript\uc5d0\uac8c.</h2><a href=\\"https://medium.com/flow-type/flow-for-typescript-users-in-2026-ad07ac0a2d92\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/flow-type/flow-for-typescript-users-in-2026-ad07ac0a2d92</a><p data-notion-block-id=\\"381e548d-8a8e-80a6-a8e6-d5acae2b8291\\">Flow\uc758 \uc7a5\uc810, \uadf8\ub9ac\uace0 Flow \uc2dc\uc120\uc5d0\uc11c \ubcf4\ub294 TypeScript\uc758 \ud5c8\uc810\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. TypeScript\ub97c \ub354 \uc798 \uc4f0\uae30 \uc704\ud574\ub77c\ub3c4 \ubcf4\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. \ucd94\uac00\ub85c \uacf5\ubcc0\uc131-\ubc18\uacf5\ubcc0\uc131-\u2026\uc758 \uad6c\uc870\ub97c \ubcf4\ub824\uba74 <a href=\\"https://medium.com/@thejameskyle/type-systems-covariance-contravariance-bivariance-and-invariance-explained-35f43d1110f8\\">Flow \uac1c\ubc1c\uc790\uc758 \uc815\ub9ac \uae00</a>\uc744, \uc774\ubcc0\uc131\uc774 TypeScript\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \ubcf4\ub824\uba74 <a href=\\"codewithstyle.info/Strict-function-types-in-TypeScript-covariance-contravariance-and-bivariance/\\">TypeScript\uc5d0\uc11c\uc758 Strict \ud0c0\uc785</a> \uae00\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"37ee548d-8a8e-80c3-a476-d46181f8aa83\\" id=\\"37ee548d-8a8e-80c3-a476-d46181f8aa83\\">\uc791\uc740 \ud06c\uae30\uc758 \uc758\uc874\uc131\uc740 \uc65c \uc911\uc694\ud560\uae4c</h2><a href=\\"https://valibot.dev/blog/dependency-size-and-cold-starts/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://valibot.dev/blog/dependency-size-and-cold-starts/</a><p data-notion-block-id=\\"37ee548d-8a8e-80b0-b97b-f97756639731\\">zod\uc640 valibot\uc758 \uc758\uc874\uc131 \ud06c\uae30\ub97c \ube44\uad50\ud558\uba74\uc11c cold-start / warm\ud55c \uc11c\ube44\uc2a4\uc5d0 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \uc790\uc138\ud788 \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uac04\ub2e8\ud55c \uae00\uc774\uc9c0\ub9cc, \uc65c <a href=\\"https://ones-to-watch.ethansup.net/news/post/32ce548d-8a8e-80d4-bf1a-d7abaa82d345#32ce548d-8a8e-8042-9f1b-cb2439cbdcbb\\">JS\ub294 \ud544\uc694\uc5c6\ub294 \uc758\uc874\uc131\uc774 \ub9ce\uc744\uae4c</a> \uae00\uacfc \ud568\uaed8 \ubcf4\uba74, \uc8fc\uae30\uc801\uc73c\ub85c\uac00 \uc544\ub2c8\ub354\ub77c\ub3c4, \uc131\ub2a5\uc744 \uc704\ud574\uc11c\ub77c\ub3c4, cold-start\uac00 \ub9ce\ub2e4\uba74 \uc758\uc874\uc131\uc744 \uc8fc\uc758\ud574\uc57c \ud568\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"379e548d-8a8e-80f3-9a94-f9522d0fbae4\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"37ee548d-8a8e-806d-9504-fd15c3dcaaf2\\" id=\\"37ee548d-8a8e-806d-9504-fd15c3dcaaf2\\">\uac04\ub2e8\ud574 \ubcf4\uc774\ub294 API\uac00 \uc5b4\ub5bb\uac8c \ub9c8\ubc95\uc774 \ub418\ub294\uac00</h2><a href=\\"https://ivakin.dev/blog/how-playwright-fixtures-work\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ivakin.dev/blog/how-playwright-fixtures-work</a><p data-notion-block-id=\\"37ee548d-8a8e-8039-bb68-f72e1f3e99fe\\">\uac04\ub2e8\ud574 \ubcf4\uc774\ub294 <code>{ page }</code> \uad6c\uc870 \ubd84\ud574 \ub4a4\uc5d0 \uc5b4\ub5a4 \ub9c8\ubc95\uc774 \uc228\uc5b4 \uc788\ub294\uc9c0 \ud480\uc5b4\ub0b4\ub294 \uae00\uc785\ub2c8\ub2e4. \ub300\ubd80\ubd84\uc740 \uc9c1\uc811 \uc4f8 \uc77c \uc5c6\ub294 \ud2b8\ub9ad\uc774\uc9c0\ub9cc, \ucf54\ub4dc\ub97c \ub370\uc774\ud130\ucc98\ub7fc \uc77d\uc5b4 \ub3d9\uc791\uc744 \uc815\ud55c\ub2e4\ub294 \ubc1c\uc0c1\uc774\ub77c \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 DX\ub97c \uc9c1\uc811 \uc124\uacc4\ud558\ub294 \uc785\uc7a5\uc774\ub77c\uba74 \ud55c \ubc88\ucbe4 \ub5a0\uc62c\ub824\ubcfc \ub9cc\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"381e548d-8a8e-8008-a9fe-fdaad4060bae\\" id=\\"381e548d-8a8e-8008-a9fe-fdaad4060bae\\">\ubd80\ubaa8\uac00 \uc790\uc2dd\uc744 \uc54c\uc544\uc57c \ud560 \ub54c</h2><a href=\\"https://www.jayfreestone.com/writing/updating-react-parents-in-response-to-changes-in-children/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jayfreestone.com/writing/updating-react-parents-in-response-to-changes-in-children/</a><p data-notion-block-id=\\"381e548d-8a8e-80bc-b93e-f70a56224a54\\">\uc790\uc2dd \ucef4\ud3ec\ub10c\ud2b8\uac00 \ubd80\ubaa8 \ucef4\ud3ec\ub10c\ud2b8/\ubd80\ubaa8\uc758 element\ub97c \uc81c\uc5b4\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\uac00 \ubb34\uc5c7\uc778\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \uc81c\uc5b4\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"381e548d-8a8e-80bd-8c5b-d3b3c99ea3ea\\" id=\\"381e548d-8a8e-80bd-8c5b-d3b3c99ea3ea\\">\ub9ac\uc561\ud2b8 \uc0dd\ud0dc\uacc4 \ud0d0\ubc29(2026)</h2><a href=\\"https://www.robinwieruch.de/react-libraries/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.robinwieruch.de/react-libraries/</a><h2 data-notion-block-id=\\"381e548d-8a8e-806f-ac90-cde2d7944a87\\" id=\\"381e548d-8a8e-806f-ac90-cde2d7944a87\\">all-new JSX, TSRX</h2><a href=\\"https://tsrx.dev/blog/rethinking-tsrx\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tsrx.dev/blog/rethinking-tsrx</a><p data-notion-block-id=\\"37ee548d-8a8e-8035-a7fa-df6e6d684953\\">\uc120\uc5b8\uc801 UI\uc6a9 TypeScript \uc5b8\uc5b4 \ud655\uc7a5\uc778 TSRX\uac00 \\"\ud3c9\ubc94\ud55c JS\uc778 \ucc99\\"\ud558\uac8c \ub450\uc9c0 \uc54a\ub3c4\ub85d \uc5b4\ub5a4 \uacb0\uc815\uc744 \ud588\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"381e548d-8a8e-80c8-bd76-c0b5aa977b03\\" id=\\"381e548d-8a8e-80c8-bd76-c0b5aa977b03\\">\ud504\ub808\uc784\uc6cc\ud06c \uc5c6\uc774 RSC \uad6c\ud604\uae30</h2><a href=\\"https://reactjs-maxxing.vercel.app/blog/how-react-server-component-integrate-with-bundler\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactjs-maxxing.vercel.app/blog/how-react-server-component-integrate-with-bundler</a><p data-notion-block-id=\\"381e548d-8a8e-805f-a4a2-c968fc366aa0\\">RSC\ub97c \uc9c1\uc811 \uad6c\ud604\ud558\uba74\uc11c \uc11c\ubc84/\ud074\ub77c\uc774\uc5b8\ud2b8\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ucabc\uac1c\uc9c0\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"381e548d-8a8e-80f8-a3b7-d4fbcefde253\\" id=\\"381e548d-8a8e-80f8-a3b7-d4fbcefde253\\">framework-agnostic \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \ub9cc\ub4e4\uae30</h2><a href=\\"https://piccalil.li/blog/framework-agnostic-design-systems-part-1/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/framework-agnostic-design-systems-part-1/</a><p data-notion-block-id=\\"37ee548d-8a8e-80e7-8528-ccb4cd95588a\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \ud2b9\uc815 \ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \ubb36\ub294 \uac8c \uc65c \uccab\ub0a0\ubd80\ud130 \ub178\ud6c4\ud654\uc778\uc9c0\uc5d0\uc11c \ucd9c\ubc1c\ud574, web components\uc640 \ubaa8\ub358 CSS\ub9cc\uc73c\ub85c \ubb38\uc11c\uae4c\uc9c0 \ud55c \ub808\ud3ec\uc5d0\uc11c \ube4c\ub4dc\ud558\ub294 \uc2e4\uc804 \uac00\uc774\ub4dc\uc785\ub2c8\ub2e4. \ubb3c\ub860 web components\uc758 \ub7ec\ub2dd\ucee4\ube0c\uac00 \ubb38\uc81c\uac00 \ub420 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \u201cJSDoc \u2192 VitePress props \uc790\ub3d9 \uc0dd\uc131\u201d \ud750\ub984\uc740 \ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"381e548d-8a8e-80db-993c-df48ded2edbd\\" id=\\"381e548d-8a8e-80db-993c-df48ded2edbd\\">Next.js\uc5d0\uc11c Active <code>&#x3C;NavLink></code>\ub9cc\ub4e4\uae30</h2><a href=\\"https://aurorascharff.no/posts/building-an-active-navlink-component-in-nextjs/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aurorascharff.no/posts/building-an-active-navlink-component-in-nextjs/</a><h2 data-notion-block-id=\\"381e548d-8a8e-80e7-a12c-fb31ad78d312\\" id=\\"381e548d-8a8e-80e7-a12c-fb31ad78d312\\">AI\ub97c \uc704\ud55c Internal \ud638\uc2a4\ud305 \ud50c\ub7ab\ud3fc \ub9cc\ub4e4\uae30</h2><a href=\\"https://shopify.engineering/quick\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shopify.engineering/quick</a><p data-notion-block-id=\\"381e548d-8a8e-807d-ae34-e76273edf619\\">\uc0ac\ub0b4 \uc9c1\uc6d0\ub9cc \uc811\uadfc\ud55c\ub2e4\ub294 \uc2e0\ub8b0 \uacbd\uacc4 \ud558\ub098\uac00 \uc5b4\ub5bb\uac8c \uc544\ud0a4\ud14d\ucc98 \uc804\uccb4\ub97c \ub2e8\uc21c\ud558\uac8c \ub9cc\ub4dc\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uad8c\ud55c\ub3c4 \uc0ac\uc774\ud2b8 \uc18c\uc720\uc790 \uac1c\ub150\ub3c4 \uc5c6\ub294 \uad6c\uc870\uac00 \uc804\ubd80 \'\uc0ac\ub0b4\ub77c\uc11c\' \uac00\ub2a5\ud588\ub2e4\ub294 \uc810\uc744 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"379e548d-8a8e-80d6-ba5c-c45b6eeaa080\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://blog.angular.dev/announcing-angular-v22-c52bb83a4664\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.angular.dev/announcing-angular-v22-c52bb83a4664</a><p data-notion-block-id=\\"37ee548d-8a8e-8076-9e18-f7aad4fa2e63\\">Angular v22\uac00 Signal Forms\xb7async reactivity\xb7Angular Aria\ub97c production-ready\ub85c \uc548\uc815\ud654\ud558\uace0 OnPush\ub97c \uc0c8 \uae30\ubcf8 change detection\uc73c\ub85c \uc0bc\uc740 consolidation \ub9b4\ub9ac\uc2a4\ub77c\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/margelo/react-native-runtimes\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/margelo/react-native-runtimes</a><p data-notion-block-id=\\"37ee548d-8a8e-80df-92b0-c0b72a86b01c\\">\ubb34\uac70\uc6b4 RN \ucef4\ud3ec\ub10c\ud2b8\ub098 \ub85c\uc9c1\uc744 \uaca9\ub9ac\ub41c \ubcf4\uc870 Hermes \ub7f0\ud0c0\uc784\uc5d0\uc11c \ub3cc\ub824 \uba54\uc778 JS \uc2a4\ub808\ub4dc\uc758 jank\ub97c \ub9c9\uc544 \uc8fc\uace0, Metro transform\uc73c\ub85c \ube4c\ub4dc \ud0c0\uc784\uc5d0 threaded boundary\ub97c \uc790\ub3d9 \ubcc0\ud658\ud558\ub294 \uba40\ud2f0 \ub7f0\ud0c0\uc784 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/rolldown/rolldown/releases/tag/v1.1.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/rolldown/rolldown/releases/tag/v1.1.0</a><p data-notion-block-id=\\"381e548d-8a8e-80a8-b6d6-f3debc01c121\\">Vite\uc758 \uae30\ubc18 \ubc88\ub4e4\ub7ec\uc778 Rust \uc81c\uc791 Rolldown\uc774 1.0 stable \uc774\ud6c4 \uccab \ub9c8\uc774\ub108\ub97c \ub0c8\uace0, \ub300\ubd80\ubd84 additive\uc9c0\ub9cc \uae30\ubcf8 \ub3d9\uc791\uc774 \ubc14\ub00c\ub294 \ubcc0\uacbd\uc774 2\uac1c \uc788\uc5b4 \uc5c5\uadf8\ub808\uc774\ub4dc \uc804 \ub9b4\ub9ac\uc2a4 \ub178\ud2b8\ub97c \uba3c\uc800 \ubd10\uc57c \ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.blog/changelog/2026-06-09-upcoming-breaking-changes-for-npm-v12/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.blog/changelog/2026-06-09-upcoming-breaking-changes-for-npm-v12/</a><p data-notion-block-id=\\"37ee548d-8a8e-8075-b1b0-dff693fcd8fe\\">2026\ub144 7\uc6d4 \uc608\uc815\uc778 npm v12\uac00 <code>npm install</code> \uae30\ubcf8\uac12\uc744 \ubcf4\uc548 \uc911\uc2ec\uc73c\ub85c \ubc14\uafd4 \uc758\uc874\uc131\uc758 install \uc2a4\ud06c\ub9bd\ud2b8\uc640 git\xb7\uc6d0\uaca9 URL \uc758\uc874\uc131\uc744 \uba85\uc2dc\uc801 \ud5c8\uc6a9 \uc5c6\uc774\ub294 \uc2e4\ud589\xb7\ud574\uc11d\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4\ub294 \uc608\uace0\uc785\ub2c8\ub2e4(11.16.0+\uc5d0\uc11c \ubbf8\ub9ac \uacbd\uace0\ub85c \ud655\uc778 \uac00\ub2a5).</p><a href=\\"https://web.dev/blog/baseline-ga-checker-update?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/blog/baseline-ga-checker-update?hl=ko</a><p data-notion-block-id=\\"37ee548d-8a8e-800d-8dd4-d2012eab2ecd\\">Baseline target\uc744 \uace0\ub97c \ub54c \uac00\uc7a5 \ubc88\uac70\ub86d\ub358 Google Analytics \ub370\uc774\ud130 \uc218\ub3d9 export \ub2e8\uacc4\ub97c \uc5c6\uc560, GA API\ub85c \ube0c\ub77c\uc6b0\uc800 \ubc84\uc804 \ub370\uc774\ud130\ub97c \uc9c1\uc811 \uac00\uc838\uc640 \ud2b9\uc815 target \uc9c0\uc6d0 \uc0ac\uc6a9\uc790 \ube44\uc728 \ub9ac\ud3ec\ud2b8\ub97c \ubc14\ub85c \uc0dd\uc131\ud574 \uc8fc\ub294 \uc5c5\ub370\uc774\ud2b8 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/wooorm/npm-esm-vs-cjs#data\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/wooorm/npm-esm-vs-cjs#data</a><p data-notion-block-id=\\"381e548d-8a8e-8080-8b3c-e3bb4c4ac066\\">\uc778\uae30 npm \ud328\ud0a4\uc9c0\uac00 ESM/dual/faux/cjs \uc911 \ubb34\uc5c7\uc744 \ub178\ucd9c\ud558\ub294\uc9c0 \uc2dc\uacc4\uc5f4\ub85c \ucd94\uc801\ud558\ub294 \ub370\uc774\ud130 \ub808\ud3ec\ub85c, \ucd5c\uadfc \ud06c\ub864 \uae30\uc900 ESM \ud3ec\ud568\uc774 33.4%\uae4c\uc9c0 \uc62c\ub790\uc9c0\ub9cc \uc5ec\uc804\ud788 \uc808\ubc18 \uc774\uc0c1\uc774 CJS\uc778 \ud604\uc2e4\uc744 \ubcf4\uc5ec\uc8fc\ub294 1\ucc28 \ub370\uc774\ud130\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"381e548d-8a8e-804a-9d88-ef1f644920ce\\" id=\\"381e548d-8a8e-804a-9d88-ef1f644920ce\\">\ubc88\uc678: \uc544\ud0a4\ud14d\uccd0\uac00 \ub354 \uc911\uc694\ud574\uc84c\ub2e4.</h2><a href=\\"https://spin.atomicobject.com/using-ai-architecture/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://spin.atomicobject.com/using-ai-architecture/</a>"}')}}]);